// Prediction function
float predict_cl(float reynolds, float alpha);

// Implementation
float predict_cl(float reynolds, float alpha) {
    float inputs[2] = {reynolds, alpha};
    float sum = 0.0f;
    
    // Process each tree
    for (int tree_idx = 0; tree_idx < NUM_TREES; tree_idx++) {
        int node_idx = tree_starts[tree_idx];
        
        // Traverse tree
        while (1) {
            const TreeNode* node = &all_nodes[node_idx];
            
            if (node->is_leaf) {
                sum += node->value;
                break;
            }
            
            // Decision node
            if (inputs[node->feature] <= node->threshold) {
                node_idx = node->left_child;
            } else {
                node_idx = node->right_child;
            }
        }
    }
    
    // Return average of all tree predictions
    return sum / NUM_TREES;
}

// Optional: Input validation function
int validate_inputs(float reynolds, float alpha) {
    return (reynolds >= RE_MIN && reynolds <= RE_MAX && 
            alpha >= ALPHA_MIN && alpha <= ALPHA_MAX);
}

